import { TransformError } from "./transform-error.js";
export const Json = {
    toData(content) {
        if (!content) {
            return {}; // fix/malformed-json - if content is empty don't parse it
        }
        try {
            return JSON.parse(content);
        }
        catch (error) {
            throw new TransformError(`Malformed JSON code: ${error.message}`);
        }
    },
    fromData(data) {
        return JSON.stringify(data, null, 2);
    },
};
